const token = ($env.ALERT_LOG_TOKEN || '').trim();
const baseHeaders = Object.assign(
  { 'Accept': 'application/json' },
  token ? { 'Authorization': 'Bearer ' + token } : {}
);
let data = null;
try {
  data = await this.helpers.httpRequest({
    method: 'GET',
    url: 'http://host.docker.internal:8091/decision/pending?overdue=1&limit=20',
    headers: baseHeaders,
    timeout: 8000,
  });
} catch (e) {
  return [];
}
const rawItems = Array.isArray(data?.items)
  ? data.items
  : (Array.isArray(data?.pending) ? data.pending : []);
const items = rawItems.filter((it) => {
  if (!it || it.hitl !== true) return false;
  const sev = String(it.severity || '').toUpperCase();
  if (!sev || sev === 'INFO') return false;
  return String(it.status || 'pending') === 'pending';
});
if (items.length === 0) return [];

const postHeaders = Object.assign({ 'Content-Type': 'application/json' }, baseHeaders);
for (const it of items) {
  try {
    await this.helpers.httpRequest({
      method: 'POST',
      url: 'http://host.docker.internal:8091/decision/escalate',
      headers: postHeaders,
      body: { hash: it.did || it.hash, agent_id: it.agent_id || '' },
      timeout: 5000,
    });
  } catch (e) { /* fail-open */ }
}

const lines = items.slice(0, 10).map((it, idx) => {
  const target = it.filename || it.filepath || it.hash || '-';
  const agent = it.agent_name || it.agent_id || '-';
  const sev = String(it.severity || 'MEDIUM').toUpperCase();
  const mins = Math.floor((it.age_secs || 0) / 60);
  return `${idx + 1}. [${sev}] ${target} (Agent: ${agent}, ${mins} mnt, ID: ${String(it.did || it.hash || '').slice(0, 12)})`;
});
const msg = [
  'ESKALASI SLA HITL (>15 Menit Belum Direspons)',
  `Total tertunda: ${items.length} insiden`,
  '',
  ...lines,
  '',
  'Harap analis segera merespons tombol keputusan pada pesan alert terkait atau tindak lanjuti melalui Dashboard SOAR.',
].join('\n');
return [{ json: { count: items.length, message: msg, items } }];

const token = ($env.ALERT_LOG_TOKEN || '').trim();
const inp = $('Cek Keputusan Lewat SLA').first().json;
const tg = ($input && $input.first && $input.first() && $input.first().json) || {};
const r = tg.result || tg;
const tgOk = (tg.ok === true) || Boolean(r && r.message_id);
let ok = false;
try {
  await this.helpers.httpRequest({
    method: 'POST',
    url: 'http://host.docker.internal:8091/log',
    headers: Object.assign({ 'Content-Type': 'application/json' }, token ? { 'Authorization': 'Bearer ' + token } : {}),
    body: {
      ts: new Date().toISOString(),
      workflow: 'SLA Eskalasi HITL',
      node: 'Kirim Eskalasi Telegram',
      severity: 'HIGH',
      title: 'Eskalasi SLA HITL',
      count: inp.count,
      escalated: true,
      telegram_ok: tgOk,
    },
    timeout: 5000,
  });
  ok = true;
} catch (e) { /* fail-open */ }
return [{ json: { logged: ok, count: inp.count } }];
